// Selection identities are row objects, never unstable sorted indices or photo names.
function photoAlbumLibraryRender(){const scroll=document.querySelector('.photo-album-scroll')?.scrollTop||0;render();const el=document.querySelector('.photo-album-scroll');if(el)el.scrollTop=scroll;}
function photoAlbumSelectionToggle(){if(_photoAlbumDeleteBusy||_photoAlbumSortBusy)return;_photoAlbumSelection=_photoAlbumSelection?null:{owner:S.me.active||'main',rows:new Set()};_photoAlbumSortOpen=false;photoAlbumLibraryRender();}
function photoAlbumPick(index){const state=_photoAlbumSelection,row=photoAlbumRows()[index];if(!state||state.owner!==(S.me.active||'main')||!row||_photoAlbumDeleteBusy)return;if(state.rows.has(row))state.rows.delete(row);else state.rows.add(row);photoAlbumLibraryRender();}
function photoAlbumSortToggle(){if(_photoAlbumDeleteBusy||_photoAlbumSortBusy)return;_photoAlbumSortOpen=!_photoAlbumSortOpen;photoAlbumLibraryRender();}
