function photoAlbumShareValid(s){return _photoAlbumShare===s&&s.owner===(S.me.active||'main')&&s.phone===phoneFriendState()&&s.phoneId===s.phone.id;}
async function photoAlbumShareBlob(row){const src=row.src;if(src.startsWith('album:')){const b=await imgGet(src.slice(6));if(!(b instanceof Blob))throw Error('照片文件缺失');return b;}if(src.startsWith('idb:')){const raw=await imgGet(src.slice(4));if(raw instanceof Blob)return raw;if(typeof raw==='string'){const r=await fetch(raw);return r.blob();}throw Error('照片文件缺失');}const r=await fetch(storedImageDisplaySource(src));if(!r.ok)throw Error('照片读取失败');return r.blob();}
function photoAlbumShareAllowed(t){if(!photoAlbumShareTargets().some(x=>x.key===t.kind+':'+t.id))return false;if(t.kind==='role'){const c=getC(t.id);return !!c&&!c.deleted&&!c.blocked&&!c._friendPending&&addedHere(c)&&!(S.couple?.gags?.[t.id]);}if(t.kind==='group'){return (S.me.active||'main')==='main'&&!!S.groups.find(g=>g.id===t.id)&&!gmMutedUntil('role',t.id,'me');}if(t.kind==='pf')return !!phoneFriendById(t.id)&&!(S.couple?.gags?.[pfGagKey(t.id)]);return !!pfGroupById(t.id)&&!gmMutedUntil('pf',t.id,phoneFriendState().id)&&!(S.couple?.gags?.[pfgGagKey(t.id)]);}
async function photoAlbumShareSend(){const s=_photoAlbumShare;if(!s||s.busy||!photoAlbumShareValid(s)||!s.photos.size||!s.targets.size)return;s.busy=true;s.status='正在发送…';photoAlbumShareProgress(s);const tasks=[],replyRoles=new Set(),replyGroups=new Set();let sent=0,failed=0,pending=0,fatal='';
 try{const destinations=photoAlbumShareTargets().filter(t=>s.targets.has(t.key));s.targetCount=destinations.length;if(!destinations.length)throw Error('所选联系人已不可用，请重新选择');for(const row of s.rows.filter(x=>s.photos.has(x))){if(!photoAlbumShareValid(s))throw Error('账号已切换，发送已停止');let blob;try{blob=await photoAlbumShareBlob(row);}catch(e){s.status=e.message||'读取失败';for(const t of destinations){const prior=s.results.get(t.key+'|'+s.rows.indexOf(row));if(prior==='sent')sent++;else if(prior==='pending')pending++;else failed++;}continue;}
 for(const t of destinations){const pair=t.key+'|'+s.rows.indexOf(row),old=s.results.get(pair);if(old==='sent'){sent++;continue;}if(old==='pending'){pending++;continue;}if(!photoAlbumShareValid(s))throw Error('账号已切换，发送已停止');if(!photoAlbumShareAllowed(t)){s.results.set(pair,'failed');failed++;continue;}
 try{if(t.kind==='role'||t.kind==='group'){const src=await compress(blob,1400,.78);if(!photoAlbumShareValid(s)||!photoAlbumShareAllowed(t))throw Error('联系人或账号已变化');const m={role:'user',type:'image',src,desc:'',visionState:'pending',id:uid(),time:Date.now(),_albumShare:photoAlbumSourceSnapshot(row)};if(t.kind==='role')msgsForAccount(t.id,s.owner).push(m);else{m.senderId='me';const g=S.groups.find(g=>g.id===t.id);g.msgs=g.msgs||[];g.msgs.push(m);}
 if(!await saveNowAsync()){const list=t.kind==='role'?msgsForAccount(t.id,s.owner):S.groups.find(g=>g.id===t.id)?.msgs;const n=list?.indexOf(m);if(n>=0)list.splice(n,1);m._deleted=true;throw Error('消息保存失败');}
 s.results.set(pair,'sent');photoAlbumRecentMark(row,'shared');sent++;if(!photoAlbumShareValid(s)||!photoAlbumShareAllowed(t))continue;if(t.kind==='role'){const list=msgsForAccount(t.id,s.owner),n=list.indexOf(m);if(n>=0)list.splice(n,1);pushMsg(t.id,m);}const job=photoAlbumShareVision(s,row,t,m);tasks.push(Promise.resolve(job).then(ok=>{if(ok&&!m._deleted&&s.owner===(S.me.active||'main')&&photoAlbumShareAllowed(t)){if(t.kind==='role'){suspicionFulfillRequest(getC(t.id),m);replyRoles.add(t.id);}else replyGroups.add(t.id);}}));
 }else{let body='',src='';for(const [size,q]of [[620,.68],[420,.58],[300,.5]]){src=await compress(blob,size,q);body=pfPack({type:'image',img:src,desc:'',_albumShareId:s.token+'|'+pair});if(body&&body.length<PHONE_FRIEND_BODY_MAX-2500)break;}if(!body||body.length>=PHONE_FRIEND_BODY_MAX-2500)throw Error('图片太大');if(!photoAlbumShareValid(s)||!photoAlbumShareAllowed(t))throw Error('联系人或账号已变化');if(t.kind==='pf'){if(typeof _pfSendBusy!=='undefined'&&_pfSendBusy[t.id])throw Error('上一条还在发送');await sendPhoneFriendBody(t.id,body,{silent:true,transport:true});}else await sendPhoneFriendGroupBody(t.id,body,{silent:true});
 const records=pfMsgList(t.kind==='pf'?s.phone.messages:s.phone.groupMessages,t.id),matches=records.filter(m=>(pfMsgPayload(m)||{})._albumShareId===s.token+'|'+pair),done=matches.some(m=>!String(m.id||'').startsWith('local_')),unknown=matches.some(m=>['unknown','sending'].includes(m.sendState));const result=done?'sent':unknown?'pending':'failed';s.results.set(pair,result);if(done){photoAlbumRecentMark(row,'shared');sent++;}else if(unknown)pending++;else failed++;}
 }catch(e){if(s.results.get(pair)!=='sent'){s.results.set(pair,'failed');failed++;}s.status=e.message||'发送失败';}if(photoAlbumShareValid(s)){s.status='已发送 '+sent+' 条图片消息'+(failed?'，未发送 '+failed:'')+(pending?'，结果待确认 '+pending:'');photoAlbumShareProgress(s);}}
 }
 }catch(e){fatal=e.message||'发送中断';s.status=fatal;}finally{s.busy=false;if(photoAlbumShareValid(s)){s.status=(fatal?fatal:'已发送 '+sent+' 条图片消息'+(failed?'，未发送 '+failed+'（可以重试）':'')+(pending?'，'+pending+' 张结果待确认，请到聊天查看':''));if(!fatal&&!failed&&!pending&&sent){s.status='已发送 '+s.photos.size+' 张照片给 '+s.targetCount+' 个联系人';_photoAlbumShare=null;_photoAlbumViewer=null;_photoAlbumSearch=null;_photoAlbumSelection=null;_photoAlbumTab='library';render();toast(s.status);}else photoAlbumShareProgress(s);}Promise.allSettled(tasks).then(()=>{if(s.owner!==(S.me.active||'main'))return;for(const id of replyRoles)if(photoAlbumShareAllowed({kind:'role',id}))scheduleReply(id);for(const id of replyGroups)if(photoAlbumShareAllowed({kind:'group',id}))aiGroupReply(id,'我分享了照片，请根据已识别的画面回复。');});}}

// One sequential vision request per distinct photo; recipients share the same factual description.
const _photoAlbumVisionTasks=new WeakMap();
async function photoAlbumEnsureVision(row,cid){
 if(!photoAlbumRows().includes(row))return false;
 if(row.desc&&row.visionState==='success')return true;
 if(_photoAlbumVisionTasks.has(row))return _photoAlbumVisionTasks.get(row);
 const owner=S.me.active||'main';
 const task=(async()=>{const draft={id:uid(),desc:'',visionState:'pending'};
  const valid=()=>owner===(S.me.active||'main')&&photoAlbumRows().includes(row);
  if(!valid())return false;
  const ok=await runVisionForMessage(cid,draft,async()=>visionPhotoSource(await photoAlbumShareBlob(row),1280,.76),'客观描述照片主体、场景和文字，不推测身份、拍摄时间、地点或共同经历。');
  if(!valid()||!ok||!draft.desc)return false;
  for(const key of ['desc','visionState','visionModel','visionProtocol','visionFallback'])if(draft[key]!==undefined)row[key]=draft[key];
  row.visionState='success';delete row.visionError;
  if(!await saveNowAsync()){delete row.desc;row.visionState='failed';return false;}
  return valid();
 })();_photoAlbumVisionTasks.set(row,task);
 try{return await task;}finally{_photoAlbumVisionTasks.delete(row);}
}
function photoAlbumShareVision(s,row,t,m){let task=s.visions.get(row);if(!task){task=s.visionTail.catch(()=>{}).then(()=>s.owner===(S.me.active||'main')?photoAlbumEnsureVision(row,t.id):false);s.visions.set(row,task);s.visionTail=task;}return task.then(ok=>{if(m._deleted||s.owner!==(S.me.active||'main'))return false;if(ok){for(const key of ['desc','visionState','visionModel','visionProtocol','visionFallback'])if(row[key]!==undefined)m[key]=row[key];delete m.visionError;}else{m.visionState='failed';m.visionError='图片理解未完成或相册记录已移除';}if(typeof save==='function')save(0);if(typeof visionStatusRefresh==='function')visionStatusRefresh(t.id);return ok;});}
function photoAlbumSourceSnapshot(row){const roleId=row.savedBy||row.uploadedBy&&row.uploadedBy!=='me'&&row.uploadedBy||'',role=roleId&&typeof getC==='function'?getC(roleId):null;return {photoId:row.id||'',category:row.category||'相簿',uploadedBy:row.uploadedBy||'unknown',savedBy:row.savedBy||'',roleName:role?(role.remark||role.name||'角色'):'',uploaderName:row.uploadedBy&&row.uploadedBy!=='me'&&row.uploadedBy!=='unknown'&&typeof getC==='function'?(getC(row.uploadedBy)?.remark||getC(row.uploadedBy)?.name||'角色'):'',source:'album'};}
function photoAlbumChatSourceText(m){const x=m?._albumShare;if(x?.source!=='album')return '';const who=x.roleName||'角色';return '[用户从相册软件分享的照片，相册照片ID：'+(x.photoId||'未记录')+'；分享时分类：'+x.category+'；'+(x.savedBy?who+'曾保存到相册；':'')+(x.uploadedBy==='me'?'用户上传':x.uploadedBy&&x.uploadedBy!=='unknown'?(x.uploaderName||'角色')+'上传':'最初上传者未记录')+'。保存或上传不代表拍摄，不能据此编造拍摄者或共同经历。] ';}
function photoAlbumSourceHTML(m){return m?._albumShare?.source==='album'?'<small class="photo-album-message-source">来自相册 · '+esc(m._albumShare.category||'相簿')+(m._albumShare.savedBy?' · '+esc(m._albumShare.roleName||'角色')+'已保存':'')+'</small>':'';}



// Search stores only bounded metadata/history; it never opens originals to match keywords.
let _photoAlbumSearch=null;
function photoAlbumSearchOpen(){if(_photoAlbumDeleteBusy||_photoAlbumSortBusy)return;_photoAlbumMenuOwner=null;_photoAlbumSearch={owner:S.me.active||'main',returnTab:_photoAlbumTab,query:'',submitted:false,kind:'photos',recent:''};_photoAlbumSelection=null;_photoAlbumSortOpen=false;render();}
function photoAlbumSearchClose(collections){if(_photoAlbumDeleteBusy||_photoAlbumSortBusy)return;const tab=collections?'collections':_photoAlbumSearch?.returnTab;_photoAlbumSearch=null;_photoAlbumSelection=null;_photoAlbumSortOpen=false;_photoAlbumTab=tab||'library';render();}
function photoAlbumSearchPrefs(){S.photoAlbum=S.photoAlbum||{items:[]};const all=S.photoAlbum.searchByAccount||(S.photoAlbum.searchByAccount={});const owner=S.me.active||'main';return all[owner]||(all[owner]={queries:[]});}
function photoAlbumRecentMark(row,kind){if(!row||!['viewed','shared'].includes(kind)||(row.accountId||'main')!==(S.me.active||'main'))return;row[kind==='viewed'?'lastViewedAt':'lastSharedAt']=Date.now();if(typeof save==='function')save(0);}
function photoAlbumDateParts(row){const value=row.takenAt??row.capturedAt;if(value==null||value==='')return null;if(typeof value==='string'){const m=value.match(/^(\d{4})-(\d{2})-(\d{2})(?:T| |$)/);if(m){const y=+m[1],month=+m[2],day=+m[3],d=new Date(y,month-1,day);return d.getFullYear()===y&&d.getMonth()===month-1&&d.getDate()===day?{y,m:month,d:day}:null;}}const d=new Date(value);return Number.isFinite(d.getTime())?{y:d.getFullYear(),m:d.getMonth()+1,d:d.getDate()}:null;}
function photoAlbumSearchMatch(row,query,now=new Date()){
 let text=String(query||'').normalize('NFKC').trim().toLowerCase();if(!text)return true;
 if(/我的喜欢|收藏/.test(text)){if(!photoAlbumHasLikes(row))return false;text=text.replace(/我的喜欢|收藏/g,' ').trim();}
 const months={'一':1,'二':2,'三':3,'四':4,'五':5,'六':6,'七':7,'八':8,'九':9,'十':10,'十一':11,'十二':12};text=text.replace(/(十二|十一|十|[一二三四五六七八九])月/g,(_,n)=>months[n]+'月');let y=null,m=null,day=null,season=null;
 text=text.replace(/(\d{4})[-/.](\d{1,2})(?:[-/.](\d{1,2}))?/g,(_,a,b,c)=>{y=+a;m=+b;if(c)day=+c;return ' ';});
 text=text.replace(/(\d{4})\s*年?/g,(_,n)=>{y=+n;return ' ';});
 text=text.replace(/(去年|今年|前年)/g,(_,n)=>{y=now.getFullYear()-(n==='去年'?1:n==='前年'?2:0);return ' ';});
 text=text.replace(/(\d{1,2})\s*月(?:份)?/g,(_,n)=>{m=+n;return ' ';}).replace(/(\d{1,2})\s*[日号]/g,(_,n)=>{day=+n;return ' ';});
 text=text.replace(/(?:^|\s)(春|夏|秋|冬)(?:季|天)?(?=\s|$)/g,(_,n)=>{season={春:[3,4,5],夏:[6,7,8],秋:[9,10,11],冬:[12,1,2]}[n];return ' ';});
 if(y!==null||m!==null||day!==null||season){const d=photoAlbumDateParts(row);if(!d||(y!==null&&d.y!==y)||(m!==null&&d.m!==m)||(day!==null&&d.d!==day)||(season&&!season.includes(d.m)))return false;}
 const hay=[row.name,row.title,row.location,row.category,...(Array.isArray(row.categories)?row.categories:[])].filter(Boolean).join(' ').normalize('NFKC').toLowerCase();return text.split(/\s+/).filter(Boolean).every(t=>hay.includes(t));
}
function photoAlbumSearchRows(){const q=_photoAlbumSearch;if(!q||q.owner!==(S.me.active||'main'))return [];let rows=photoAlbumRows().filter(r=>photoAlbumSearchMatch(r,q.query));if(q.recent){const key={viewed:'lastViewedAt',edited:'lastEditedAt',shared:'lastSharedAt'}[q.recent];rows=rows.filter(r=>Number.isFinite(r[key])).sort((a,b)=>b[key]-a[key]);}return rows;}
function photoAlbumSearchSubmit(value){const q=_photoAlbumSearch;if(!q||q.owner!==(S.me.active||'main')||_photoAlbumDeleteBusy||_photoAlbumSortBusy)return;value=String(value||'').trim().slice(0,120);q.query=value;q.submitted=!!value;q.recent='';_photoAlbumSelection=null;_photoAlbumSortOpen=false;if(value){const p=photoAlbumSearchPrefs();p.queries=[value,...(p.queries||[]).filter(x=>x!==value)].slice(0,12);if(typeof save==='function')save(0);}render();}
function photoAlbumSearchHistory(index){const value=photoAlbumSearchPrefs().queries[index];if(value)photoAlbumSearchSubmit(value);}
function photoAlbumSearchClearHistory(){if(!_photoAlbumSearch||_photoAlbumSearch.owner!==(S.me.active||'main'))return;photoAlbumSearchPrefs().queries=[];if(typeof save==='function')save(0);render();}
function photoAlbumSearchRecent(kind){if(!['viewed','edited','shared'].includes(kind)||!_photoAlbumSearch)return;_photoAlbumSearch.query='';_photoAlbumSearch.recent=kind;_photoAlbumSearch.submitted=true;_photoAlbumSelection=null;render();}
function photoAlbumSearchKind(kind){if(!_photoAlbumSearch||_photoAlbumDeleteBusy)return;_photoAlbumSearch.kind=kind==='collections'?'collections':'photos';_photoAlbumSelection=null;render();}
function photoAlbumSearchPick(index){const row=photoAlbumSearchRows()[index];if(row)photoAlbumPick(photoAlbumRows().indexOf(row));}
function photoAlbumSearchSelectAll(){if(!_photoAlbumSelection||_photoAlbumDeleteBusy)return;const rows=photoAlbumSearchRows(),all=rows.every(r=>_photoAlbumSelection.rows.has(r));for(const r of rows)all?_photoAlbumSelection.rows.delete(r):_photoAlbumSelection.rows.add(r);photoAlbumLibraryRender();}
function photoAlbumSearchView(index){const rows=photoAlbumSearchRows(),row=rows[index];if(!row)return;photoAlbumOpen(photoAlbumRows().indexOf(row));_photoAlbumViewer.rows=rows;_photoAlbumViewer.index=index;render();}
function renderPhotoAlbumSearch(){
 const q=_photoAlbumSearch;if(_photoAlbumSelection?.owner!==q.owner)_photoAlbumSelection=null;const selecting=!!_photoAlbumSelection,rows=photoAlbumSearchRows(),prefs=photoAlbumSearchPrefs(),recentLabel={viewed:'最近查看',edited:'最近编辑',shared:'最近共享'}[q.recent];
 const grid=()=>`<div class="photo-album-grid">${rows.map((r,i)=>`<button data-photo-move-id="${esc(r.id||'')}" class="photo-album-grid-cell ${selecting&&_photoAlbumSelection.rows.has(r)?'checked':''}" aria-label="${esc(r.title||r.name||'照片')}" ${selecting?`aria-pressed="${_photoAlbumSelection.rows.has(r)}"`:''} onclick="${selecting?'photoAlbumSearchPick':'photoAlbumSearchView'}(${i})">${photoAlbumImageHTML(r.thumbSrc||r.src,r.name||'照片')}${selecting&&_photoAlbumSelection.rows.has(r)?'<span class="photo-album-check">✓</span>':''}</button>`).join('')}</div>`;
 const collections=[...PHOTO_ALBUM_GROUPS,'我的喜欢'].map(label=>{const found=rows.filter(r=>label==='我的喜欢'?photoAlbumHasLikes(r):r.category===label||r.categories?.includes(label));if(!found.length)return '';return `<section class="photo-search-collection"><h2>${label} · ${found.length}</h2><div class="photo-search-recent">${found.slice(0,24).map(r=>`<button class="photo-search-tile" onclick="photoAlbumSearchView(${rows.indexOf(r)})">${photoAlbumImageHTML(r.thumbSrc||r.src,r.name||label)}${photoAlbumLikeBadge(r)}<span>${esc(r.location||r.title||label)}<small>${esc(photoAlbumTaken(r).date)}</small></span></button>`).join('')}</div></section>`;}).join('');
 return `<div class="page photo-album-page photo-search-page" data-photo-album="search"><div class="photo-album-scroll"><header class="photo-album-head"><h1>${selecting?`<button class="photo-album-glass photo-album-select" onclick="photoAlbumSearchSelectAll()">全选</button>`:'搜索'}</h1><div class="photo-album-head-actions"><button class="photo-album-glass photo-album-round" aria-label="图库排序" onclick="photoAlbumSortToggle()">${photoAlbumIcon('dots')}</button><button class="photo-album-glass ${selecting?'photo-album-round':'photo-album-select'}" aria-label="${selecting?'取消选择':'选择照片'}" onclick="photoAlbumSearchSelectionToggle()">${selecting?'×':'选择'}</button></div>${_photoAlbumSortOpen?photoAlbumSortHTML():''}</header>${q.submitted?`${selecting?'':`<nav class="photo-album-glass photo-search-tabs"><button class="${q.kind==='photos'?'selected':''}" onclick="photoAlbumSearchKind('photos')">照片</button><button class="${q.kind==='collections'?'selected':''}" onclick="photoAlbumSearchKind('collections')">精选集</button></nav>`}<h2 class="photo-search-result-label">${recentLabel||'最佳结果'} <small>${rows.length} 个结果</small></h2>${q.kind==='collections'&&!selecting?collections:grid()}${rows.length?'':'<p class="photo-album-empty">没有符合条件的照片</p>'}`:`<section class="photo-search-home"><h2>最近项目</h2><div class="photo-search-recent">${[['viewed','最近查看'],['edited','最近编辑'],['shared','最近共享']].map(([kind,label])=>{const key={viewed:'lastViewedAt',edited:'lastEditedAt',shared:'lastSharedAt'}[kind],cover=photoAlbumRows().filter(r=>r[key]).sort((a,b)=>b[key]-a[key])[0];return `<button class="photo-search-tile photo-album-glass" onclick="photoAlbumSearchRecent('${kind}')">${cover?photoAlbumImageHTML(cover.thumbSrc||cover.src,label):photoAlbumIcon('library')}<span>${label}</span></button>`;}).join('')}</div><div class="photo-search-history-head"><h2>最近搜索</h2><button class="photo-album-glass" aria-label="清除最近搜索" onclick="photoAlbumSearchClearHistory()">清除</button></div><div class="photo-search-history">${(prefs.queries||[]).map((x,i)=>`<button class="photo-album-glass" onclick="photoAlbumSearchHistory(${i})">${esc(x)}</button>`).join('')||'<p>搜索记录会显示在这里</p>'}</div></section>`}</div>${selecting?`<footer class="photo-album-footer"><button class="photo-album-glass photo-album-search" aria-label="分享所选照片" ${!_photoAlbumSelection.rows.size?'disabled':''} onclick="photoAlbumShareOpen()">${photoAlbumIcon('share')}</button><span class="photo-album-selection-count">已选择 ${_photoAlbumSelection.rows.size} 张照片</span><button class="photo-album-glass photo-album-search" aria-label="删除所选照片" ${!_photoAlbumSelection.rows.size?'disabled':''} onclick="photoAlbumDeleteSelected()">${photoAlbumIcon('trash')}</button></footer>`:`<footer class="photo-album-footer photo-search-footer"><button class="photo-album-glass photo-album-round" aria-label="返回精选集" onclick="photoAlbumSearchClose(true)">${photoAlbumIcon('collections')}</button><form class="photo-album-glass photo-search-input" onsubmit="event.preventDefault();photoAlbumSearchSubmit(this.elements.query.value)">${photoAlbumIcon('search')}<input name="query" type="search" maxlength="120" value="${esc(q.query)}" placeholder="搜索你的图库…" aria-label="搜索你的图库" enterkeyhint="search"></form><button class="photo-album-glass photo-album-round" aria-label="退出搜索" onclick="photoAlbumSearchClose()">×</button></footer>`}</div>`;
}

function photoAlbumSearchSelectionToggle(){if(!_photoAlbumSearch||_photoAlbumDeleteBusy||_photoAlbumSortBusy)return;_photoAlbumSearch.submitted=true;photoAlbumSelectionToggle();}

// Collection menu starts the native photo picker directly in the user click.
let _photoAlbumMenuOwner=null;
function photoAlbumMenuToggle(){if(_photoAlbumDeleteBusy||_photoAlbumSortBusy)return;_photoAlbumMenuOwner=_photoAlbumMenuOwner===null?(S.me.active||'main'):null;photoAlbumLibraryRender();}
function photoAlbumMenuPick(index){if(_photoAlbumMenuOwner!==(S.me.active||'main')||!PHOTO_ALBUM_GROUPS[index])return;document.getElementById('photo-album-category-file-'+index)?.click();}
function photoAlbumMenuChosen(index,input){if(_photoAlbumMenuOwner!==(S.me.active||'main')||!PHOTO_ALBUM_GROUPS[index])return;const files=Array.from(input.files||[]).filter(f=>f.type.startsWith('image/'));if(!files.length)return;_photoAlbumMenuOwner=null;photoAlbumUploadOpen(PHOTO_ALBUM_GROUPS[index]);photoAlbumChooseFiles({files});}
function photoAlbumMenuHTML(){return `<div class="photo-album-sort-dismiss" onclick="photoAlbumMenuToggle()"></div><div class="photo-album-glass photo-collection-menu" role="menu" aria-label="按分类上传照片"><h2>上传到分类</h2>${PHOTO_ALBUM_GROUPS.map((label,index)=>`<div class="photo-collection-menu-row"><button role="menuitem" aria-label="上传到${label}" onclick="photoAlbumMenuPick(${index})"><span>${label}</span><span class="photo-collection-upload">上传 ${photoAlbumIcon('share')}</span></button><input id="photo-album-category-file-${index}" type="file" accept="image/*" multiple hidden onchange="photoAlbumMenuChosen(${index},this)"></div>`).join('')}</div>`;}

// Couple access belongs to one role and one account. Revocation invalidates in-flight work.
let _photoAlbumCommentTail=Promise.resolve();const _photoAlbumCommentActive=new WeakSet();
function photoAlbumCoupleAllowed(c){const cp=S.couple;return !!(c&&cp&&cp.cid===c.id&&cp.albumAuth===true&&cp.albumAuthCid===c.id&&(S.me.active||'main')==='main'&&!c.blocked&&!c.deleted);}
function photoAlbumPermissionToggle(){const cp=S.couple,c=cp&&getC(cp.cid);if(!c)return;const enabled=photoAlbumCoupleAllowed(c);cp.albumAuth=!enabled;cp.albumAuthCid=enabled?null:c.id;cp.albumAuthEpoch=(+cp.albumAuthEpoch||0)+1;for(const r of S.photoAlbum?.items||[])if(r.commentState==='pending'){r.commentState='failed';r.commentError='相册权限已变化，请重新留言';}save();render();toast(enabled?'已收回相册权限':'已允许当前情侣保存照片和留言');}
function photoAlbumPermissionHTML(){const c=S.couple&&getC(S.couple.cid);return `<div class="it" data-couple-permission="albumAuth"><span>相册权限<br><small>仅当前情侣可以查看、保存、留言和点喜欢；默认关闭</small></span><span role="switch" tabindex="0" aria-label="相册权限" aria-checked="${photoAlbumCoupleAllowed(c)}" class="sw ${photoAlbumCoupleAllowed(c)?'on':''}" onclick="photoAlbumPermissionToggle()" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();photoAlbumPermissionToggle();}"></span></div><div class="it" onclick="openApp('album')"><span>打开相册</span><span class="v">›</span></div>`;}
function photoAlbumImportLegacy(c){if(!c||S.couple?.cid!==c.id||(S.me.active||'main')!=='main')return;const old=coupleAlbumItems(c);if(!old.length)return;S.photoAlbum=S.photoAlbum||{items:[]};S.photoAlbum.items=S.photoAlbum.items||[];const imported=S.photoAlbum.legacyImported||(S.photoAlbum.legacyImported={});let changed=false;for(const x of old){const origin='legacy:'+c.id+':'+x.source+':'+x.id;if(imported[origin])continue;if(S.photoAlbum.items.some(r=>r.originKey===origin||x.source==='wechat'&&r.originKey==='chat:'+c.id+':'+x.id)){imported[origin]=true;changed=true;continue;}S.photoAlbum.items.push({id:uid(),accountId:'main',src:x.src,category:'共享相簿',name:'共同相册照片',uploadedAt:x.time||Date.now(),takenAt:null,desc:x.desc,visionState:x.visionState,coupleRoleId:c.id,uploadedBy:x.owner==='ta'?c.id:x.owner==='me'?'me':'unknown',savedBy:x.owner==='ta'?c.id:'',originKey:origin});imported[origin]=true;changed=true;}if(changed)save();}
function photoAlbumRoleRows(c){return photoAlbumCoupleAllowed(c)?photoAlbumRows().filter(r=>!r.coupleRoleId||r.coupleRoleId===c.id):[];}
function photoAlbumRolePrompt(c){if(!photoAlbumCoupleAllowed(c))return '';photoAlbumImportLegacy(c);const rows=photoAlbumRoleRows(c).filter(r=>r.desc&&r.visionState==='success').slice(0,20);return '\n# 相册权限（仅你作为当前情侣获得）\n你可以查看用户相册里的真实照片；只有觉得有意义或用户让你保存时才输出 [存共同相册|分类|一句简短留言]，保存的是聊天里最近一张真实图片。分类只能选：回忆、相簿、人物与宠物、精选照片、共享相簿、最近的日子、旅程。宠物和人物优先人物与宠物，明确旅行画面用旅程，特别珍视的照片可用精选照片或回忆，不确定用共享相簿。不重复识图，只依据已有真实描述选分类。用户手动调整过的位置要尊重，再次保存同一张不会改动原位置。成功会显示保存提示。不要声称已经完成尚未执行的保存。只有用户主动要看相册回忆或当前话题明确相关时才分享照片，绝不无缘无故分享；一次回复最多一张，近期不重复同一张，上传删除通知不发回忆卡。你可以针对下列已存照片自然回忆，使用 [回忆相册|照片ID|一句简短留言] 发出可点开的回忆卡；不得猜画面、拍摄日期或编造共同经历。浏览用户正在分享的相册照片、应用户请求看相册或分享相关回忆时，可以按自己的喜好输出[喜欢相册|照片ID]，不必每张点赞，不得无缘无故翻相册点赞，成功由系统记录。用户收藏与你的喜欢分开。\n'+rows.map(r=>JSON.stringify({id:r.id,category:r.category,location:r.location||'',takenAt:r.takenAt||'未知',description:r.desc,categoryBy:r.categoryBy||'unknown',provenance:photoAlbumSourceSnapshot(r),comment:r.roleComment?.text||'',likedByMe:!!r.likedByMe,likedByYou:!!r.roleLikes?.[c.id]})).join('\n');}
async function photoAlbumRoleSave(c,image,text,category){if(!photoAlbumCoupleAllowed(c)||!image||!image.src||image.pending||image._deleted)return false;const cp=S.couple,epoch=+cp.albumAuthEpoch||0;S.photoAlbum=S.photoAlbum||{items:[]};S.photoAlbum.items=S.photoAlbum.items||[];const key='chat:'+c.id+':'+image.id;let row=S.photoAlbum.items.find(r=>((image._albumShare?.source==='album'&&r.id===image._albumShare.photoId)||r.originKey===key||r.originKey==='legacy:'+c.id+':wechat:'+image.id)&&r.accountId==='main'),created=!row;if(image._albumShare?.source==='album'&&(!row||!photoAlbumRoleRows(c).includes(row)))return false;const oldComment=row?.roleComment,oldSavedBy=row?.savedBy;if(!row){row={id:uid(),accountId:'main',src:image.src,category:photoAlbumRoleCategory(image,category),categoryBy:'role',name:'角色珍藏的照片',uploadedAt:Date.now(),takenAt:null,coupleRoleId:c.id,uploadedBy:image.role==='assistant'?c.id:'me',savedBy:c.id,originKey:key,desc:image.desc||'',visionState:image.visionState||''};S.photoAlbum.items.push(row);}row.savedBy=c.id;if(text)row.roleComment={roleId:c.id,text:String(text).slice(0,160),time:Date.now()};const rollback=()=>{if(oldSavedBy===undefined)delete row.savedBy;else row.savedBy=oldSavedBy;if(created){const i=S.photoAlbum.items.indexOf(row);if(i>=0)S.photoAlbum.items.splice(i,1);}else if(oldComment)row.roleComment=oldComment;else delete row.roleComment;};try{if(!await saveNowAsync())throw Error('照片未确认保存');if(S.couple!==cp||(+cp.albumAuthEpoch||0)!==epoch||!photoAlbumCoupleAllowed(c)){rollback();save();return false;}toast((c.remark||c.name)+'已存入相册 · '+row.category);if(!text)photoAlbumQueueComments([row]);return true;}catch(_){rollback();save();toast('照片保存失败，请检查存储空间');return false;}}
const _photoAlbumEvents=new Map();
function photoAlbumOperationContext(){const c=S.couple&&getC(S.couple.cid);return photoAlbumCoupleAllowed(c)?{cp:S.couple,epoch:+S.couple.albumAuthEpoch||0,cid:c.id}:null;}
function photoAlbumOperationContextValid(x){return !!x&&x.cp===S.couple&&x.epoch===(+S.couple.albumAuthEpoch||0)&&photoAlbumCoupleAllowed(getC(x.cid));}
function photoAlbumEventNoteValid(note,cid,aid){const tags=[...String(note||'').matchAll(/\[相册操作\|([^\]]+)\]/g)];return tags.every(tag=>{const e=_photoAlbumEvents.get(tag[1]);return !!e&&e.cid===cid&&e.owner===(aid||S.me.active||'main')&&S.couple===e.cp&&(+e.cp.albumAuthEpoch||0)===e.epoch&&photoAlbumCoupleAllowed(getC(cid));});}
function photoAlbumNotifyOperation(kind,count,rows,context){const c=S.couple&&getC(S.couple.cid);if(!photoAlbumCoupleAllowed(c)||typeof scheduleFeatureReply!=='function')return;const cp=S.couple,epoch=+cp.albumAuthEpoch||0;if(context&&(context.cp!==cp||context.epoch!==epoch||context.cid!==c.id))return;const token=uid();_photoAlbumEvents.set(token,{cp,epoch,cid:c.id,owner:S.me.active||'main'});while(_photoAlbumEvents.size>100)_photoAlbumEvents.delete(_photoAlbumEvents.keys().next().value);const known=rows.filter(r=>photoAlbumRoleRows(c).includes(r)&&r.desc&&r.visionState==='success');const detail='[相册操作|'+token+'] 用户'+(kind==='delete'?'删除':kind==='move'?'移动':'上传')+'了 '+count+' 张相册照片。这是同一次操作，只发一次自然微信回应，不逐张刷屏，不发送回忆卡。'+(kind==='delete'?'被删除的照片已从相册移除，不再作为当前相册记忆使用，也不要索要恢复。':(kind==='move'?'用户重新分类到：'+rows.map(r=>r.category).join('、')+'。记住新位置，尊重用户整理，不擅自移回。':'')+'已识别 '+known.length+' 张；尚未识别的不要猜画面。可以结合下面一两张真实描述说话：'+known.slice(0,2).map(r=>r.desc).join('；'));scheduleFeatureReply(c.id,featureEventNote('相册变化',detail),150,null,'main');}
function photoAlbumQueueComments(rows,notify){const c=S.couple&&getC(S.couple.cid);if(!photoAlbumCoupleAllowed(c))return;const context={cp:S.couple,epoch:+S.couple.albumAuthEpoch||0,cid:c.id};for(const row of rows)_photoAlbumCommentTail=_photoAlbumCommentTail.catch(()=>{}).then(()=>photoAlbumOperationContextValid(context)?photoAlbumGenerateComment(row,c):undefined);if(notify)_photoAlbumCommentTail=_photoAlbumCommentTail.catch(()=>{}).then(()=>photoAlbumNotifyOperation('upload',rows.length,rows,context));return _photoAlbumCommentTail;}

async function photoAlbumGenerateComment(row,c){if(!photoAlbumCoupleAllowed(c)||!photoAlbumRoleRows(c).includes(row)||row.roleComment?.roleId===c.id||_photoAlbumCommentActive.has(row))return;_photoAlbumCommentActive.add(row);const cp=S.couple,epoch=+cp.albumAuthEpoch||0,owner=S.me.active||'main',valid=()=>S.couple===cp&&(+cp.albumAuthEpoch||0)===epoch&&(S.me.active||'main')===owner&&photoAlbumCoupleAllowed(c)&&photoAlbumRoleRows(c).includes(row);row.commentState='pending';if(cur().p==='album'&&_photoAlbumViewer)photoAlbumCommentRefresh();try{const route=typeof roleServerModelRoute==='function'?roleServerModelRoute(c):S.settings?.chat;if(!route?.base||!route?.key)throw Error('请先配置外置聊天接口');if(!await photoAlbumEnsureVision(row,c.id)){if(!valid())return;throw Error('图片理解未成功');}if(!valid())return;const answer=String(await chatAPI([{role:'system',content:'你是'+(c.name||'情侣')+'。人设：'+String(c.persona||'').slice(0,4000)+'\n请给恋人上传的一张照片留一句简短自然的话，最多60字。只依据真实描述，不猜身份、经历、日期，不输出旁白或系统提示。若这张照片确实符合你的人设和喜好，可在末尾加[喜欢照片]；不喜欢或不确定就不要加。不要每张都点赞。'},{role:'user',content:'照片真实描述：'+row.desc+'\n用户填写标题：'+(row.title||'')+'；地区：'+(row.location||'未填写')}],{max:180,independentRoleModel:true,routeIndex:typeof roleChatRouteIndex==='function'?roleChatRouteIndex(c):undefined,aux:c.model==='aux',diagnosticRoleId:c.id,diagnosticChannel:'album',roleInterceptPurpose:'album-comment'})).trim();if(!valid())return;const wantsLike=/[\[【]喜欢照片[\]】]/.test(answer),text=answer.replace(/[\[【]喜欢照片[\]】]/g,'').trim();if(!text||/[\[【]/.test(text)||text.length>160)throw Error('留言格式不正确，请重试');row.roleComment={roleId:c.id,text,time:Date.now()};row.commentState='done';delete row.commentError;if(!await saveNowAsync()){delete row.roleComment;throw Error('留言未确认保存');}if(wantsLike&&valid())await photoAlbumRoleLike(row,c);}catch(e){if(!valid())return;row.commentState='failed';row.commentError=String(e.message||'留言失败').slice(0,140);save();}finally{_photoAlbumCommentActive.delete(row);if(valid()&&cur().p==='album'&&_photoAlbumViewer)photoAlbumCommentRefresh();}}
function photoAlbumCommentRetry(){const row=_photoAlbumViewer?.rows[_photoAlbumViewer.index];if(row)photoAlbumQueueComments([row]);}
function photoAlbumCommentHTML(row){const c=S.couple&&getC(S.couple.cid);if(!photoAlbumCoupleAllowed(c)||row.coupleRoleId&&row.coupleRoleId!==c.id)return '';const note=row.roleComment?.roleId===c.id?row.roleComment:null;return `<section class="photo-role-comment" aria-label="角色的照片留言"><span class="photo-role-avatar">${av(c.avatar||'🙂')}</span><div><strong>${esc(c.remark||c.name)}</strong><p>${esc(note?.text||(row.commentState==='pending'?'正在看这张照片…':'还没有留下评论'))}</p>${!note&&!_photoAlbumCommentActive.has(row)?`<button onclick="photoAlbumCommentRetry()">${row.commentState==='failed'?'重新留言':'请ta留下句话'}</button>`:''}</div></section>`;}
function photoAlbumMemoryHTML(m){return `<button class="photo-memory-card photo-album-glass" onclick="event.stopPropagation();photoAlbumMemoryOpen(${jq(m.photoId)})"><span class="photo-memory-label">我们的相册 · 回忆</span><span class="photo-memory-image">${photoAlbumImageHTML(m.photoSrc||'','回忆照片')}</span><strong>${esc(m.content||'留在相册里的这一刻')}</strong><small>${esc(m.photoLocation||'')} ${esc(m.photoDate||'拍摄时间未知')} · 查看照片 ›</small></button>`;}
function photoAlbumMemoryOpen(id){if(appLocked('album')){toast('相册已被锁定');return;}const rows=photoAlbumRows(),index=rows.findIndex(r=>r.id===id);if(index<0){toast('照片已移除或不属于当前账号');return;}go('album');photoAlbumOpen(index);}
function photoAlbumConsumeMemory(content,c,outcome,userText){let sent=false;return String(content||'').replace(/[\[【]\s*回忆相册\s*[|｜]([^|｜\]】]+)[|｜]([^\]】]+)[\]】]/g,(_,id,text)=>{const row=photoAlbumRoleRows(c).find(r=>r.id===id.trim()&&r.desc&&r.visionState==='success');if(!row||sent||!photoAlbumMemoryRelevant(row,userText)){roleInterceptDiagnosticAction(outcome,false);return '';}sent=true;row.lastMemorySharedAt=Date.now();const list=msgsForAccount(c.id,'main');list.push({id:uid(),role:'assistant',type:'albummemory',time:Date.now(),photoId:row.id,photoSrc:row.thumbSrc||row.src,photoLocation:row.location||'',photoDate:photoAlbumTaken(row).date,content:text.trim().slice(0,160)});save();roleInterceptDiagnosticAction(outcome,true);return '';});}

function photoAlbumReferencedSources(root){const refs=new Set(),seen=new WeakSet();function walk(v){if(typeof v==='string'){if(v.startsWith('album:'))refs.add(v);return;}if(!v||typeof v!=='object'||seen.has(v))return;seen.add(v);for(const x of Object.values(v))walk(x);}walk(root);return refs;}

function photoAlbumMemoryRelevant(row,text){text=String(text||'');if(!text||/\[功能事件|\[相册操作/.test(text))return false;const requested=/(相册|照片|回忆).{0,12}(看看|看一下|分享|发来|发给|给我|找)|(?:看看|看一下|分享|发来|发给|给我|找).{0,12}(相册|照片|回忆)/.test(text);if(requested)return true;if(Date.now()-(+row.lastMemorySharedAt||0)<7*86400000)return false;const fact=[row.desc,row.title,row.location].join(' '),themes=text.match(/海边|大海|湖面|湖水|旅行|旅程|宠物|小猫|小狗|猫咪|演唱会|日落|雪山|生日|花园|公园|博物馆/g)||[];if(themes.some(x=>fact.includes(x)))return true;return !!(row.location&&row.location.length>=2&&text.includes(row.location));}

function photoAlbumRoleCategory(image,requested){if(PHOTO_ALBUM_GROUPS.includes(requested))return requested;const desc=image.visionState==='success'?String(image.desc||''):'';if(/猫咪|小猫|一只猫|猫在|猫的|猫坐|小狗|狗狗|一只狗|狗在|宠物|人像|肖像|人物照片|合照|自拍/.test(desc))return '人物与宠物';if(/旅行|旅游|景点|雪山|海边|博物馆|迪士尼|埃菲尔铁塔/.test(desc))return '旅程';return '共享相簿';}
let _photoAlbumMoveBusy=false,_photoAlbumHold=null,_photoAlbumDrag=null,_photoAlbumDragSuppress=0;
async function photoAlbumMove(row,category,owner,options={}){owner=owner||S.me.active||'main';if(_photoAlbumMoveBusy||_photoAlbumDeleteBusy||_photoAlbumSortBusy||owner!==(S.me.active||'main')||!photoAlbumRows().includes(row)||!PHOTO_ALBUM_GROUPS.includes(category))return false;if(row.category===category&&!row.categories?.some(x=>x!==category))return true;_photoAlbumMoveBusy=true;const before={category:row.category,categories:row.categories,categoryBy:row.categoryBy},context=photoAlbumOperationContext();row.category=category;delete row.categories;row.categoryBy='user';const rollback=()=>{for(const key of Object.keys(before)){if(before[key]===undefined)delete row[key];else row[key]=before[key];}};try{if(!await saveNowAsync())throw Error('分类未确认保存');if(owner!==(S.me.active||'main')){rollback();save();return false;}if(!photoAlbumRows().includes(row))return false;_photoAlbumExpanded.add(category);toast('已移到'+category);if(photoAlbumOperationContextValid(context))photoAlbumNotifyOperation('move',1,[row],context);return true;}catch(_){rollback();save();if(owner===(S.me.active||'main'))toast('移动未保存，照片仍在原分组');return false;}finally{_photoAlbumMoveBusy=false;if(!options.keepViewer&&owner===(S.me.active||'main')&&typeof cur==='function'&&cur().p==='album')render();}}
function photoAlbumDragCancel(){if(_photoAlbumHold){clearTimeout(_photoAlbumHold.timer);_photoAlbumHold=null;}if(_photoAlbumDrag){_photoAlbumDrag.host.remove();_photoAlbumDrag=null;}}
function photoAlbumDropPick(index){const drag=_photoAlbumDrag,category=PHOTO_ALBUM_GROUPS[index];if(!drag||!category)return;photoAlbumDragCancel();_photoAlbumDragSuppress=Date.now()+900;return photoAlbumMove(drag.row,category,drag.owner);}
function photoAlbumDragStart(event,point){if(_photoAlbumSelection||_photoAlbumMoveBusy||_photoAlbumDeleteBusy||_photoAlbumSortBusy||_photoAlbumShare||_photoAlbumUpload)return;const tile=event.target.closest?.('[data-photo-move-id]');if(!tile)return;const row=photoAlbumRows().find(r=>r.id===tile.dataset.photoMoveId);if(!row)return;photoAlbumDragCancel();const hold={row,owner:S.me.active||'main',x:point.clientX,y:point.clientY,touchId:point.identifier,timer:null};_photoAlbumHold=hold;hold.timer=setTimeout(()=>{if(_photoAlbumHold!==hold||hold.owner!==(S.me.active||'main')||!photoAlbumRows().includes(row)||!document.querySelector('.photo-album-page'))return;const host=document.createElement('div');host.className='photo-album-move-overlay';host.innerHTML='<div class="photo-album-glass photo-album-move-tray" role="dialog" aria-label="移动照片分组"><strong>移到分组</strong><p>拖到分组后松手，也可以直接点选</p><div>'+PHOTO_ALBUM_GROUPS.map((label,i)=>'<button class="photo-album-glass" data-album-drop="'+i+'" onclick="photoAlbumDropPick('+i+')">'+esc(label)+(row.category===label?' · 当前':'')+'</button>').join('')+'</div><button class="photo-album-move-cancel" onclick="photoAlbumDragCancel()">取消</button></div><div class="photo-album-move-ghost">'+photoAlbumImageHTML(row.thumbSrc||row.src,row.name||'照片')+'</div>';document.querySelector('.photo-album-page').appendChild(host);_photoAlbumDrag={row,owner:hold.owner,host,active:true,ghost:host.querySelector('.photo-album-move-ghost')};_photoAlbumHold=null;_photoAlbumDragSuppress=Date.now()+900;photoAlbumDragPosition(hold.x,hold.y);photoAlbumHydrateSoon();},450);}
function photoAlbumDragPosition(x,y){const d=_photoAlbumDrag;if(!d)return;const rect=d.host.getBoundingClientRect(),sx=rect.width/(d.host.offsetWidth||rect.width)||1,sy=rect.height/(d.host.offsetHeight||rect.height)||1;d.ghost.style.transform='translate3d('+Math.max(0,(x-rect.left)/sx-36)+'px,'+Math.max(0,(y-rect.top)/sy-36)+'px,0)';const target=document.elementFromPoint(x,y)?.closest('[data-album-drop]');d.host.querySelectorAll('[data-album-drop]').forEach(el=>el.classList.toggle('drop-active',el===target));}
function photoAlbumDragMove(event,point){if(_photoAlbumDrag&&(!_photoAlbumDrag.host.isConnected||_photoAlbumDrag.owner!==(S.me.active||'main')||!photoAlbumRows().includes(_photoAlbumDrag.row)))photoAlbumDragCancel();if(_photoAlbumHold&&Math.hypot(point.clientX-_photoAlbumHold.x,point.clientY-_photoAlbumHold.y)>10)photoAlbumDragCancel();if(_photoAlbumDrag?.active){event.preventDefault();event.stopPropagation();photoAlbumDragPosition(point.clientX,point.clientY);}}
function photoAlbumDragEnd(event,point,cancel){if(_photoAlbumHold)photoAlbumDragCancel();if(!_photoAlbumDrag)return;if(cancel){photoAlbumDragCancel();return;}event.preventDefault();event.stopPropagation();_photoAlbumDragSuppress=Date.now()+900;const target=document.elementFromPoint(point.clientX,point.clientY)?.closest('[data-album-drop]');if(target)photoAlbumDropPick(Number(target.dataset.albumDrop));else{_photoAlbumDrag.active=false;_photoAlbumDrag.ghost.style.display='none';}}
if(typeof window!=='undefined'&&typeof document!=='undefined'&&document.addEventListener){
 document.addEventListener('pointerdown',e=>{if(e.pointerType!=='touch'&&e.button===0)photoAlbumDragStart(e,e);},true);
 document.addEventListener('pointermove',e=>{if(e.pointerType!=='touch')photoAlbumDragMove(e,e);},true);
 document.addEventListener('pointerup',e=>{if(e.pointerType!=='touch')photoAlbumDragEnd(e,e,false);},true);
 document.addEventListener('pointercancel',e=>{if(e.pointerType!=='touch')photoAlbumDragEnd(e,e,true);},true);
 document.addEventListener('touchstart',e=>{if(e.touches.length===1)photoAlbumDragStart(e,e.touches[0]);else photoAlbumDragCancel();},{passive:true,capture:true});
 document.addEventListener('touchmove',e=>{if(e.touches.length===1)photoAlbumDragMove(e,e.touches[0]);else photoAlbumDragCancel();},{passive:false,capture:true});
 document.addEventListener('touchend',e=>{if(e.changedTouches[0])photoAlbumDragEnd(e,e.changedTouches[0],false);},{passive:false,capture:true});
 document.addEventListener('touchcancel',e=>photoAlbumDragEnd(e,e.changedTouches[0]||e,true),true);
 document.addEventListener('click',e=>{if(Date.now()<_photoAlbumDragSuppress&&e.target.closest?.('[data-photo-move-id]')){e.preventDefault();e.stopImmediatePropagation();}},true);
 document.addEventListener('contextmenu',e=>{if(e.target.closest?.('[data-photo-move-id]'))e.preventDefault();},true);
 document.addEventListener('dragstart',e=>{if(e.target.closest?.('[data-photo-move-id]'))e.preventDefault();},true);
 document.addEventListener('keydown',e=>{if(e.key==='Escape')photoAlbumDragCancel();});
}

// Metadata is edited in place; image bytes, cached vision and role provenance stay unchanged.
let _photoAlbumEdit=null;
function photoAlbumEditOpen(mode){if(_photoAlbumEdit||_photoAlbumDeleteBusy)return;const v=_photoAlbumViewer,row=v?.rows[v.index];if(!row||!photoAlbumRows().includes(row))return;const stamp=photoAlbumTaken(row),parts=photoAlbumDateParts(row);_photoAlbumEdit={row,owner:S.me.active||'main',mode:mode==='category'?'category':'metadata',category:row.category||'回忆',busy:false,date:parts?String(parts.y).padStart(4,'0')+'-'+String(parts.m).padStart(2,'0')+'-'+String(parts.d).padStart(2,'0'):'',time:stamp.time==='—'?'':stamp.time,title:row.title||'',location:row.location||''};const host=document.querySelector('.photo-viewer');if(host)host.insertAdjacentHTML('beforeend',photoAlbumEditHTML());}
function photoAlbumEditHTML(){const e=_photoAlbumEdit;if(!e||e.owner!==(S.me.active||'main'))return '';if(e.mode==='category')return photoAlbumCategoryHTML(e);return `<div class="photo-meta-overlay"><div class="photo-meta-dismiss" onclick="photoAlbumEditClose()"></div><form class="photo-album-glass photo-meta-panel" onsubmit="event.preventDefault();photoAlbumEditSave(this)"><h2>调整照片信息</h2><label>日期<input name="date" type="date" value="${esc(e.date)}"></label><label>时间<input name="time" type="time" value="${esc(e.time)}"></label><label>地点<input name="location" maxlength="120" placeholder="填写拍摄地点" value="${esc(e.location)}"></label><label>标题<input name="title" maxlength="120" placeholder="给照片一个标题" value="${esc(e.title)}"></label><p class="photo-meta-error" role="status"></p><button class="photo-meta-done" type="submit">完成</button><button type="button" class="photo-meta-cancel" onclick="photoAlbumEditClose()">取消</button></form></div>`;}
function photoAlbumEditClose(){if(_photoAlbumEdit?.busy)return;_photoAlbumEdit=null;document.querySelector('.photo-meta-overlay')?.remove();}
async function photoAlbumEditSave(form){const e=_photoAlbumEdit;if(!e||e.busy||e.owner!==(S.me.active||'main')||!photoAlbumRows().includes(e.row))return;const date=form.elements.date.value,time=form.elements.time.value,location=form.elements.location.value.trim().slice(0,120),title=form.elements.title.value.trim().slice(0,120),error=form.querySelector('.photo-meta-error');if((date&&!time)||(!date&&time)){error.textContent='日期和时间需要一起填写，也可以一起留空。';return;}if(date){const m=date.match(/^(\d{4})-(\d{2})-(\d{2})$/),d=m&&new Date(+m[1],+m[2]-1,+m[3]);if(!m||d.getFullYear()!==+m[1]||d.getMonth()+1!==+m[2]||d.getDate()!==+m[3]||!/^([01]\d|2[0-3]):[0-5]\d$/.test(time)){error.textContent='请填写有效的日期和时间。';return;}}const row=e.row,keys=['takenAt','capturedAt','location','title','lastEditedAt','metadataBy'],prior=Object.fromEntries(keys.map(k=>[k,{had:Object.prototype.hasOwnProperty.call(row,k),value:row[k]}]));e.busy=true;form.querySelector('.photo-meta-done').disabled=true;row.takenAt=date?date+'T'+time:null;delete row.capturedAt;row.location=location;row.title=title;row.lastEditedAt=Date.now();row.metadataBy='user';try{if(!await saveNowAsync())throw Error('保存失败');if(e.owner!==(S.me.active||'main')||!photoAlbumRows().includes(row))throw Error('账号或照片已变化');_photoAlbumEdit=null;document.querySelector('.photo-meta-overlay')?.remove();if(_photoAlbumViewer){const host=document.querySelector('.photo-viewer'),current=_photoAlbumViewer.rows[_photoAlbumViewer.index],stamp=photoAlbumTaken(current);if(host){host.querySelector('.photo-view-date strong').textContent=stamp.date;host.querySelector('.photo-view-date span').textContent=stamp.time;host.querySelector('.photo-view-metadata').innerHTML=photoAlbumMetadataHTML(current);}}toast('照片信息已保存');}catch(err){for(const k of keys)prior[k].had?row[k]=prior[k].value:delete row[k];error.textContent=err.message||'保存失败，请重试';}finally{e.busy=false;form.querySelector('.photo-meta-done').disabled=false;}}
function photoAlbumShareProgress(s){if(!photoAlbumShareValid(s))return;const host=document.querySelector('.photo-album-share');if(!host)return;const status=host.querySelector('.photo-share-status');if(status)status.textContent=s.status;for(const button of host.querySelectorAll('button'))button.disabled=s.busy;const send=host.querySelector('.photo-share-send');if(send)send.textContent=s.busy?'发送中':s.targets.size?'发送':'×';}

function photoAlbumShareSelectionUI(s){const host=document.querySelector('.photo-album-share');if(!host){render();return;}host.querySelector('.photo-share-head h1').textContent='已选择 '+s.photos.size+' 张照片';host.querySelector('.photo-share-head p').textContent=s.targets.size?'已选择 '+s.targets.size+' 个联系人':'选择要分享的联系人';const send=host.querySelector('.photo-share-send');send.classList.toggle('ready',!!s.targets.size);send.textContent=s.targets.size?'发送':'×';send.setAttribute('aria-label',s.targets.size?'发送照片':'关闭分享');send.setAttribute('onclick',s.targets.size?'photoAlbumShareSend()':'photoAlbumShareClose()');host.querySelectorAll('.photo-share-photo').forEach((el,i)=>{const checked=s.photos.has(s.rows[i]);el.setAttribute('aria-pressed',String(checked));const tick=el.querySelector('.photo-share-tick');tick.classList.toggle('on',checked);tick.textContent=checked?'✓':'';});const targets=photoAlbumShareTargets();host.querySelectorAll('.photo-share-person').forEach((el,i)=>{const checked=s.targets.has(targets[i]?.key);el.setAttribute('aria-pressed',String(checked));const face=el.querySelector('.photo-share-avatar'),tick=face.querySelector('.photo-album-check');if(!checked)tick?.remove();else if(!tick)face.insertAdjacentHTML('beforeend','<i class="photo-album-check">✓</i>');});}

function photoAlbumMetadataHTML(row){return (row.title?'<strong>'+esc(row.title)+'</strong>':'')+(row.location?'<span>'+esc(row.location)+'</span>':'');}

// Favorites are a derived collection, never a replacement for the original category.
const _photoAlbumLikeBusy=new WeakSet(),_photoAlbumRoleLikeBusy=new WeakSet();
function photoAlbumHasLikes(row){return !!(row.likedByMe||Object.values(row.roleLikes||{}).some(x=>x&&x.time));}
function photoAlbumLikeBadge(row){return photoAlbumHasLikes(row)?'<i class="photo-album-like-badge" aria-label="有喜欢记录">'+photoAlbumIcon('heart')+'</i>':'';}
function photoAlbumLikeButton(row){return '<button class="photo-user-like '+(row.likedByMe?'on':'')+'" aria-label="'+(row.likedByMe?'取消我的收藏':'收藏照片')+'" aria-pressed="'+!!row.likedByMe+'" onclick="photoAlbumUserLike()">'+photoAlbumIcon('heart')+'</button>';}
function photoAlbumLikeInfo(row){const likes=Object.entries(row.roleLikes||{}).filter(([id,x])=>x&&x.time);return '<div class="photo-like-info">'+(row.likedByMe?'<span>你已收藏</span>':'')+likes.map(([id,x])=>'<span class="photo-role-like">'+(typeof av==='function'?av(x.avatar||'🙂'):'')+esc(x.name||'角色')+'喜欢</span>').join('')+'</div>';}
function photoAlbumLikeRefresh(){const row=_photoAlbumViewer?.rows[_photoAlbumViewer.index],host=typeof document==='undefined'?null:document.querySelector('.photo-viewer');if(!row||!host)return;const button=host.querySelector('.photo-user-like');if(button){button.classList.toggle('on',!!row.likedByMe);button.setAttribute('aria-pressed',String(!!row.likedByMe));button.setAttribute('aria-label',row.likedByMe?'取消我的收藏':'收藏照片');button.disabled=_photoAlbumLikeBusy.has(row);}const info=host.querySelector('.photo-like-info');if(info)info.outerHTML=photoAlbumLikeInfo(row);}
async function photoAlbumUserLike(){const row=_photoAlbumViewer?.rows[_photoAlbumViewer.index],owner=S.me.active||'main';if(!row||!photoAlbumRows().includes(row)||_photoAlbumLikeBusy.has(row))return false;_photoAlbumLikeBusy.add(row);const previous=row.likedByMe;row.likedByMe=!previous;photoAlbumLikeRefresh();try{if(!await saveNowAsync())throw Error('收藏保存失败');if(owner!==(S.me.active||'main')||!photoAlbumRows().includes(row))throw Error('账号或照片已变化');return true;}catch(_){if(previous===undefined)delete row.likedByMe;else row.likedByMe=previous;save();toast('收藏未保存，请重试');return false;}finally{_photoAlbumLikeBusy.delete(row);photoAlbumLikeRefresh();}}
async function photoAlbumRoleLike(row,c){if(!photoAlbumRoleRows(c).includes(row)||!row.desc||row.visionState!=='success'||row.roleLikes?.[c.id]||_photoAlbumRoleLikeBusy.has(row))return false;const cp=S.couple,epoch=+cp.albumAuthEpoch||0,owner=S.me.active||'main';_photoAlbumRoleLikeBusy.add(row);row.roleLikes=row.roleLikes||{};const record={name:c.remark||c.name||'角色',avatar:c.avatar||'',time:Date.now()};row.roleLikes[c.id]=record;const rollback=()=>{if(row.roleLikes?.[c.id]===record)delete row.roleLikes[c.id];};try{if(!await saveNowAsync())throw Error('喜欢未保存');if(S.couple!==cp||(+cp.albumAuthEpoch||0)!==epoch||owner!==(S.me.active||'main')||!photoAlbumRoleRows(c).includes(row)){rollback();save();return false;}return true;}catch(_){rollback();save();return false;}finally{_photoAlbumRoleLikeBusy.delete(row);photoAlbumLikeRefresh();}}
async function photoAlbumConsumeLikes(content,c,outcome,userText){let count=0;const tags=[...String(content||'').matchAll(/[\[【]喜欢相册[|｜]([^\]】]+)[\]】]/g)];for(const tag of tags){const row=photoAlbumRoleRows(c).find(r=>r.id===tag[1].trim()),last=typeof msgsForAccount==='function'?msgsForAccount(c.id,'main').filter(m=>m.role==='user').slice(-1)[0]:null,text=String(userText||''),shared=!!text.trim()&&last?.type==='image'&&last._albumShare?.photoId===row?.id,requested=/相册|回忆|照片/.test(text)&&!/功能事件|相册操作/.test(text),memory=row&&String(content).includes('回忆相册|'+row.id+'|')&&photoAlbumMemoryRelevant(row,userText);const denied=/(?:不要|别|不用|不许|禁止).{0,20}(?:点赞|收藏|点.*心|喜欢)/.test(text);const allowed=!denied&&row&&count<3&&(shared||requested||memory)&&!/功能事件|相册操作/.test(text);const ok=allowed?await photoAlbumRoleLike(row,c):false;if(ok)count++;if(typeof roleInterceptDiagnosticAction==='function')roleInterceptDiagnosticAction(outcome,!!ok);}return String(content||'').replace(/[\[【]喜欢相册[|｜]([^\]】]+)[\]】]/g,'');}

function photoAlbumCommentRefresh(){const row=_photoAlbumViewer?.rows[_photoAlbumViewer.index],host=typeof document!=='undefined'?document.querySelector('.photo-role-comment-host'):null;if(row&&host)host.innerHTML=photoAlbumCommentHTML(row)+photoAlbumLikeInfo(row);}

function photoAlbumCategoryHTML(e){return `<div class="photo-meta-overlay"><div class="photo-meta-dismiss" onclick="photoAlbumEditClose()"></div><form class="photo-album-glass photo-meta-panel photo-category-panel" role="dialog" aria-label="调整照片分类" onsubmit="event.preventDefault();photoAlbumCategorySave(this)"><h2>调整照片分类</h2><p class="photo-category-current">当前分类：${esc(e.row.category||'回忆')}</p><div class="photo-category-options">${PHOTO_ALBUM_GROUPS.map(label=>`<label class="photo-album-glass"><input type="radio" name="category" value="${esc(label)}" ${label===e.category?'checked':''}><span>${esc(label)}</span></label>`).join('')}</div><p class="photo-category-note">爱心、留言和拍摄信息会保留。“我的喜欢”根据爱心自动收集。</p><p class="photo-meta-error" role="status"></p><button class="photo-meta-done" type="submit">完成</button><button class="photo-meta-cancel" type="button" onclick="photoAlbumEditClose()">取消</button></form></div>`;}
async function photoAlbumCategorySave(form){const e=_photoAlbumEdit;if(!e||e.mode!=='category'||e.busy||e.owner!==(S.me.active||'main')||!photoAlbumRows().includes(e.row))return;const category=form.elements.category.value,error=form.querySelector('.photo-meta-error');if(!PHOTO_ALBUM_GROUPS.includes(category)){error.textContent='请选择一个照片分类';return;}e.busy=true;const button=form.querySelector('.photo-meta-done');button.disabled=true;try{const ok=await photoAlbumMove(e.row,category,e.owner,{keepViewer:true});if(_photoAlbumEdit!==e)return;if(ok){_photoAlbumEdit=null;document.querySelector('.photo-meta-overlay')?.remove();}else error.textContent='分类未保存，请重试。';}finally{e.busy=false;button.disabled=false;}}
